# C1–10: source page A23, physical PDF1237. Complete the squares.
for k,h,j,r2 in [(1,3,-1,25),(2,-2,-8,100),(3,0,0,65),(4,-1,5,130)]:
 correct=f'({fmt(x-h)})² + ({fmt(y-j)})² = {r2}'
 put('C',k,choice('Circle equation',correct,f'({fmt(x+h)})² + ({fmt(y+j)})² = {r2+1}',f'({fmt(x-h)})² + ({fmt(y-j)})² = {2*r2}'),why=f'A circle centered at ({h},{j}) has (x−h)²+(y−k)²=r². Here r²={r2}; for a supplied point compute its squared distance from the center.')
for k,A,B,K in [(5,-4,10,13),(6,0,6,2),(7,1,0,0),(8,R(1,2),2,R(1,16)),(9,-R(1,2),R(1,2),-R(1,2))]:
 h=-A/2;j=-B/2;r2=s.sympify(A)**2/4+s.sympify(B)**2/4-K
 # sympify rational centering avoids all implicit decimal approximations in verification.
 h=-s.sympify(A)/2;j=-s.sympify(B)/2
 put('C',k,n('Center · x',h),n('Center · y',j),n('Radius',s.sqrt(r2)),exact('Standard form · radius squared',r2),why=f'Divide by the common quadratic coefficient, then complete both squares: (x−({fmt(h)}))²+(y−({fmt(j)}))²={fmt(r2)}. The right side is positive, so this is a nondegenerate circle.',limited=True)
 eqcheck(f'C{k} completed squares',(x-h)**2+(y-j)**2-r2,x*x+y*y+A*x+B*y+K)
put('C',10,choice('Condition for a nondegenerate circle','a²+b²−4c > 0','a²+b²−4c < 0','a²+b²−4c = 0'),choice('Center','(−a/2, −b/2)','(a/2, b/2)','(−a, −b)'),choice('Radius','√(a²+b²−4c)/2','a²+b²−4c','√(a²+b²+4c)/2'),why='Completing the square gives (x+a/2)²+(y+b/2)²=(a²+b²−4c)/4. A positive right side gives a circle, zero gives one point, and a negative right side gives no real points.')
# Standard-form graph contracts verify type plus location and geometry, not a drawing.
def parab(k,h,j,coef,axis='vertical'):
 expr=coef*((x-h)**2 if axis=='vertical' else (y-j)**2)+(j if axis=='vertical' else h)
 direction=('up' if coef>0 else 'down') if axis=='vertical' else ('right' if coef>0 else 'left')
 put('C',k,choice('Curve','Parabola','Ellipse','Hyperbola'),n('Vertex · x',h),n('Vertex · y',j),choice('Opening direction',direction,*[q for q in ['up','down','left','right'] if q!=direction]),exact('Standard form · '+('y' if axis=='vertical' else 'x'),expr),why=f'Complete the square to obtain {"y" if axis=="vertical" else "x"}={fmt(expr)}. The vertex is ({h},{j}); coefficient {coef} makes the parabola open {direction}.',limited=True)
def ellipse(k,h,j,ax2,by2):
 put('C',k,choice('Curve','Ellipse','Parabola','Hyperbola'),n('Center · x',h),n('Center · y',j),n('Horizontal semiaxis',s.sqrt(ax2)),n('Vertical semiaxis',s.sqrt(by2)),why=f'Complete squares and divide to get (x−({h}))²/({ax2})+(y−({j}))²/({by2})=1. The positive denominators are the squared horizontal and vertical semiaxes.',limited=True)
def hyper(k,h,j,ax2,by2,axis='horizontal'):
 slope=s.sqrt(s.sympify(by2)/ax2)
 desc='Left and right' if axis=='horizontal' else 'Up and down'
 put('C',k,choice('Curve','Hyperbola','Ellipse','Parabola'),n('Center · x',h),n('Center · y',j),choice('Branches open',desc,'Up and down' if axis=='horizontal' else 'Left and right','Closed oval'),n('Center-to-vertex distance',s.sqrt(ax2 if axis=='horizontal' else by2)),n('Positive asymptote slope',slope),why=f'The squared terms have opposite signs. The center is ({h},{j}); x and y denominator squares are {ax2} and {by2}. The positive squared term gives the opening axis, and the asymptotes have slopes ±√({by2}/{ax2}).',limited=True)
parab(11,0,0,-1);hyper(12,0,0,1,1,'vertical');ellipse(13,0,0,16,4);parab(14,0,0,-2,'horizontal');hyper(15,0,0,25,16);ellipse(16,0,0,4,25);ellipse(17,0,0,R(1,4),1);parab(18,0,2,1);parab(19,-1,0,1,'horizontal');hyper(20,0,0,25,9);hyper(21,0,0,9,1,'vertical');ellipse(22,0,0,5,2)
put('C',23,choice('Graph description','Rectangular hyperbola with branches in quadrants I and III','Rectangular hyperbola with branches in quadrants II and IV','Ellipse centered at the origin'),choice('Asymptotes','x=0 and y=0','x=4 and y=4','y=x and y=−x'),why='Rewrite xy=4 as y=4/x. Both coordinates have the same sign. The coordinate axes are asymptotes, and the graph has no points on either axis.',limited=True)
parab(24,-1,-1,1);ellipse(25,1,2,4,9);ellipse(26,0,2,9,16);parab(27,3,4,1);hyper(28,2,0,1,1);parab(29,4,0,-1,'horizontal');parab(30,-2,-3,R(1,2),'horizontal');ellipse(31,3,0,4,1);ellipse(32,2,-3,9,4)
put('C',33,choice('Bounded region','0 ≤ x ≤ 3 and x² ≤ y ≤ 3x','0 ≤ x ≤ 3 and 3x ≤ y ≤ x²','−3 ≤ x ≤ 0 and x² ≤ y ≤ 3x'),choice('Intersection points','(0,0) and (3,9)','(0,0) and (3,3)','(0,0) and (−3,9)'),why='Solve x²=3x: x(x−3)=0. Between x=0 and x=3, 3x−x²=x(3−x)≥0, so the line is the upper boundary.',limited=True)
put('C',34,choice('Bounded region','−5/2 ≤ x ≤ 2 and (x−2)/2 ≤ y ≤ 4−x²','−5/2 ≤ x ≤ 2 and 4−x² ≤ y ≤ (x−2)/2','−2 ≤ x ≤ 5/2 and (x−2)/2 ≤ y ≤ 4−x²'),choice('Intersection points','(−5/2,−9/4) and (2,0)','(−2,0) and (5/2,−9/4)','(−5/2,9/4) and (2,0)'),why='The line is y=(x−2)/2. Equating it to 4−x² gives (2x+5)(x−2)=0. The downward parabola lies above the line between the two roots.',limited=True)
